\section{Algorithm}
\begin{algorithm}
\caption{Score update}
\label{alg:score-update}
\begin{algorithmic}[1]
\Require A graph $G=(V,E)$ with $n$ nodes and $m$ edges
\Ensure The score vector $\mathrm{score}[v]$ for every node $v \in V$
\For{each node $v \in V$}
  \State update $\mathrm{score}[v]$
\EndFor
\State \Return the score vector $\mathrm{score}$
\end{algorithmic}
\end{algorithm}
